  if (!('a' in args) || !('b' in args) || !('operation' in args)) {
    throw new Error('Missing required field: a, b, or operation');
  }

  // Validate types
  if (typeof args.a !== 'number') {
    throw new Error('a must be a number');
  }
  if (typeof args.b !== 'number') {
    throw new Error('b must be a number');
  }

  // Validate operation
  if (!OPERATIONS.has(args.operation)) {
    throw new Error('Unsupported operation: ' + args.operation);
  }

  const { a, b, operation } = args;
  let result;

  switch (operation) {
    case 'add':
      result = a + b;
      break;
    case 'subtract':
      result = a - b;
      break;
    case 'multiply':
      result = a * b;
      break;
